// Bundle only explicitly selected Job notifications; manual menu sends stay unchanged.
function jiraPlusWebhook(value){return new URL(String(value).trim().replace(/\\&/g,'&').replace(/&amp;/g,'&')).href;}
function jiraPlusRecipients(values){return [...new Set(values.map(x=>String(x).trim().toLowerCase()).filter(Boolean))].sort().join(';');}
function jiraPlusMergeDeliveries(entries,job){
 const grouped=new Map(),order=['coe','sprint','epic'];
 for(const entry of [...entries].sort((a,b)=>order.indexOf(a.menu)-order.indexOf(b.menu))){const p=entry.payload,key=String(p.projectKey||'');if(!key)throw Error('合并通知缺少项目 Key，未发送');const url=jiraPlusWebhook(entry.url);if(!grouped.has(key))grouped.set(key,[]);const group=grouped.get(key);if(group.length&&group[0].url!==url)throw Error(key+' 扫描期间通知地址已变化，未发送');group.push({...entry,url});}
 return [...grouped.values()].map(items=>{const first=items[0],names=items.map(x=>({coe:'COE',sprint:'Sprint',epic:'Epic'})[x.menu]),title=first.payload.projectKey+' · '+names.join(' / '),emails=items.map(x=>x.payload.email).filter(e=>e?.enabled),recipients=[...new Set(emails.flatMap(e=>e.recipients||String(e.to||'').split(';')).filter(Boolean))];
 if(job.email&&!recipients.length)throw Error(title+' 未配置邮件收件人');
 const cards=items.flatMap(x=>x.payload.attachments||[]),body=items.flatMap(item=>(item.payload.attachments||[]).flatMap(c=>[{type:'TextBlock',text:({coe:'COE',sprint:'Sprint',epic:'Epic'})[item.menu]||'扫描结果',weight:'Bolder',size:'Medium',separator:true,wrap:true},...(c.content?.body||[]),...(c.content?.actions?.length?[{type:'ActionSet',actions:c.content.actions}]:[])])),attachment={contentType:'application/vnd.microsoft.card.adaptive',content:{$schema:'http://adaptivecards.io/schemas/adaptive-card.json',type:'AdaptiveCard',version:'1.2',msteams:{width:'Full',entities:cards.flatMap(c=>c.content?.msteams?.entities||[])},body:[{type:'TextBlock',text:title,weight:'Bolder',size:'Large',wrap:true},...body]}};
 const oversized=new TextEncoder().encode(JSON.stringify(attachment)).length>26*1024,missing=items.some(x=>x.payload.teams?.enabled===false||!(x.payload.attachments||[]).length);if(job.teams&&(oversized||missing)&&!job.email)throw Error('合并结果超过 Teams 大小限制或包含仅邮件结果，请启用邮件后重试');
 const teams=job.teams&&!oversized&&!missing,email=job.email?{enabled:true,recipients,to:recipients.join(';'),subject:'[Jira+] '+title,bodyText:emails.map((e,i)=>names[i]+'\n'+(e.bodyText||'')).join('\n\n'),bodyHtml:emails.map(e=>'<div style="margin-bottom:24px">'+(e.bodyHtml||'')+'</div>').join(''),attachments:job.attach?emails.flatMap(e=>e.attachments||[]):[]}:{enabled:false};
 return {url:first.url,payload:{type:'message',reportType:'job-summary',projectKey:first.payload.projectKey,text:title+'\n'+items.map(x=>x.payload.text||x.payload.summary||'扫描完成').join('\n\n'),summary:title,menus:items.map(x=>x.menu),teams:{enabled:teams},deliveryMode:teams?'teams-and-email':'email-only',attachments:teams?[attachment]:[],email},emailOnly:job.teams&&!teams};
 });
}
function jiraPlusValidateDeliveries(deliveries,job,target){for(const d of deliveries){const current=target(d.payload.projectKey+'-1');if(!current)throw Error(d.payload.projectKey+' 通知未启用，未发送');if(jiraPlusWebhook(current.webhook)!==d.url)throw Error(d.payload.projectKey+' Webhook 配置已变化，未发送');if(job.email&&jiraPlusRecipients(current.recipients||[])!==jiraPlusRecipients(d.payload.email.recipients))throw Error(d.payload.projectKey+' 邮件收件人配置已变化，未发送');}}
async function jiraPlusFlush(job){const entries=jiraPlusPending||[];jiraPlusPending=null;const deliveries=jiraPlusMergeDeliveries(entries,job);jiraPlusValidateDeliveries(deliveries,job,key=>hub.target(key));for(const d of deliveries){await new Promise((resolve,reject)=>GM_xmlhttpRequest({method:'POST',url:d.url,headers:{'Content-Type':'application/json'},data:JSON.stringify(d.payload),timeout:30000,onload:r=>r.status>=200&&r.status<300?resolve():reject(Error('合并通知失败 HTTP '+r.status+'；未自动重试')),onerror:()=>reject(Error('合并通知网络失败，结果未知；未自动重试')),ontimeout:()=>reject(Error('合并通知超时，结果未知；未自动重试'))}));}const menus=[...new Set(entries.map(e=>e.menu))].map(m=>({coe:'COE',sprint:'Sprint',epic:'EPIC'})[m]).join(' / ');return deliveries.some(d=>d.emailOnly)?'所选数量超过 Teams 大小限制，所选数据只通过邮件发送（'+menus+'）':deliveries.length?'已按项目合并提交 '+menus+'；最终投递请查看工作流':'扫描完成，没有可推送的数据';}
